import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"Drawbar","description":"","frontmatter":{},"headers":[],"relativePath":"components/drawbar.md","filePath":"components/drawbar.md"}'),r={name:"components/drawbar.md"};function n(s,e,i,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="drawbar" tabindex="-1">Drawbar <a class="header-anchor" href="#drawbar" aria-label="Permalink to &quot;Drawbar&quot;">​</a></h1><p>Drawbar is the bar of drawing tools that floats at the bottom centre of the stage, with the switches of the aids after the tools.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the tools that change what a press on the stage does. The application passes the tools as a list and says which one is current; <code>onselect</code> reports the tool that is pressed. A tool that acts at once (delete) is in the list too, with <code>tone: &#39;danger&#39;</code>, and the application leaves the current tool as it was. Aids that are on or off while any tool is in use, such as snapping or a grid, go in <code>toggles</code>; each reports the state it asks for, and the application keeps it. The actions of a panel go in its <a href="./toolbar">Toolbar</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tools</code></td><td>required</td><td>The tools, <code>DrawbarTool[]</code></td></tr><tr><td><code>toggles</code></td><td><code>[]</code></td><td>The switches after the tools, <code>DrawbarToggle[]</code></td></tr><tr><td><code>current</code></td><td></td><td>The id of the current tool</td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the tool that is pressed</td></tr><tr><td><code>label</code></td><td></td><td>The name of the bar</td></tr><tr><td><code>bottom</code></td><td><code>md</code></td><td>The distance from the bottom edge: <code>0</code> or a gap step</td></tr><tr><td><code>column</code></td><td><code>false</code></td><td>One column in the flow of its container</td></tr></tbody></table><p>A <code>DrawbarTool</code> is <code>{ id, label, icon, kbd?, group?, tone?, disabled? }</code>: <code>icon</code> is an icon name or component, <code>kbd</code> the key that picks the tool, shown in its tooltip, and <code>group</code> puts consecutive tools together.</p><p>A <code>DrawbarToggle</code> is <code>{ id, label, icon, on, onchange?, kbd?, disabled?, popover? }</code>: <code>on</code> is its state, <code>onchange</code> is called with the state it asks for, and <code>popover</code>, a snippet of <code>(close)</code>, holds the settings of the aid, shown in a <a href="./popover">Popover</a> when the switch is pressed. <code>onchange</code> may be left out, typically for a switch with a <code>popover</code>; pressing a switch without it, or its item in the More menu, does nothing.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Each tool is a ghost icon button, pressed (<code>aria-pressed</code>) and on when it is current, and shows its name and its key in a <a href="./tooltip">Tooltip</a>; a tool with <code>tone: &#39;danger&#39;</code> turns red on hover. The switches are the same buttons in one more group after the tools, pressed and on while they are on. A switch with a <code>popover</code> opens it instead of calling <code>onchange</code>: lined up with the switch&#39;s end, above the bar however far the bar is from the bottom of the window (below it only when there is no room above). It has <code>aria-haspopup=&quot;true&quot;</code> and <code>aria-expanded</code>, and <code>on</code> only says what it shows; the application changes it from the settings in the popover. The tools of a group sit gap-2xs apart and the groups gap-md apart, with pad-sm inside and one strong line around the whole bar on the panel surface; no line runs between tools. The bar is placed absolutely in its positioned container, centred, <code>bottom</code> from its bottom edge, and never wider than the container less gap-md on each side. When the buttons do not fit, those that do not fit fold into a More menu, an icon button in a group of its own at the right end: the current tool always shows, then the others from the start as long as they fit. In the menu a tool shows its icon and a switch a check mark when it is on, each with its key. The widths are measured again when the container or the text size changes; the buttons never shrink.</p><p>With <code>column</code>, the tools and the switches stand in one column, the tools of a group gap-2xs apart and the groups gap-md apart, and the bar has <code>aria-orientation=&quot;vertical&quot;</code>. It is in the flow of its container (<code>position: static</code>), so <code>bottom</code> does not apply and the container places it, as the place above the Fab of a <a href="./../workbench/shell">Shell</a> does; nothing folds into More.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/drawbar/" title="Drawbar" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/drawbar/" target="_blank" rel="noopener">Drawbar</a></figcaption></figure>',13)])])}const w=t(r,[["render",n]]);export{b as __pageData,w as default};
